const loora=n=>E(`${n}, tāpat kā ${n==='Loora'?'Loore':'Loora'}, ir Eleonoras forma.`,`${n}, как и ${n==='Loora'?'Loore':'Loora'}, — форма имени Элеонора.`,`${n}, like ${n==='Loora'?'Loore':'Loora'}, is a form of Eleonora.`,`${n}, kaip ir ${n==='Loora'?'Loore':'Loora'}, – Eleonoros forma.`,`${n}, nagu ka ${n==='Loora'?'Loore':'Loora'}, on nime Eleonora kuju.`);
const saare=n=>E([`${n} (Saare, Saari) ir sieviešu vārds, kas dažkārt atvasināts no mājvārda Saare; formu Saari ievietoja M. Tenisona 1884. gada kalendārs (17. maijā). To saista arī ar Sāru.`],[`${n} (Saare, Saari) — женское имя, иногда образованное от названия хутора Saare; форму Saari дал календарь М. Тыниссона 1884 года (17 мая). Его связывают и с именем Сара.`],[`${n} (Saare, Saari) is a woman’s name sometimes taken from the farm name Saare; the form Saari comes from Mats Tõnisson’s calendar of 1884 (17 May). It is also linked with Sarah.`],[`${n} (Saare, Saari) – moters vardas, kartais kilęs iš sodybos vardo Saare; formą Saari pateikė M. Tõnissono 1884 metų kalendorius (gegužės 17 d.). Jis siejamas ir su Sara.`],[`${n} (Saare ~ Saari) on naisenimi, mis mõnikord tuletatud talunimest Saare; teisend Saari on M. Tõnissoni kalendrist 1884. a. (17. V). Vrd. Sara(h).`]);
const raina=n=>E([`${n}, tāpat kā ${n==='Raina'?'Raini':'Raina'}, ir jauns vārds: vecākie zināmie pieraksti ir Tartu dzimšanas reģistrā 1962. gadā un 1963. gada Igaunijas vārdu sarakstā.`],[`${n}, как и ${n==='Raina'?'Raini':'Raina'}, — новое имя: самые ранние известные записи — в тартуском регистре рождений 1962 года и в эстонском списке имён 1963 года.`],[`${n}, like ${n==='Raina'?'Raini':'Raina'}, is a new name: its oldest known records are the Tartu birth register of 1962 and the Estonian name list of 1963.`],[`${n}, kaip ir ${n==='Raina'?'Raini':'Raina'}, – naujas vardas: seniausi žinomi įrašai yra 1962 metų Tartu gimimų registre ir 1963 metų Estijos vardų sąraše.`],[`${n}, nagu ka ${n==='Raina'?'Raini':'Raina'}, on uus nimi: vanimad teadaolevad allikad on Tartu sünniregister 1962 ja 1963. a. vabariiklik nimestik.`]);
const leen=n=>E(`${n} (Leen, Leena, Leene, Leeni, Leeno, Leenu) ir vārdu Helēna un Magdalēna forma; visbiežāk pamatvārds ir Helēna.`,`${n} (Leen, Leena, Leene, Leeni, Leeno, Leenu) — форма имён Елена и Магдалина; чаще всего исходное имя — Елена.`,`${n} (Leen, Leena, Leene, Leeni, Leeno, Leenu) is a form of Helena and Magdalena; most often the base name is Helena.`,`${n} (Leen, Leena, Leene, Leeni, Leeno, Leenu) – vardų Elena ir Magdalena forma; dažniausiai pagrindinis vardas yra Elena.`,`${n} (Leen, Leena, Leene, Leeni, Leeno, Leenu) on nimede Helena ja Magdalena kuju; alusnimeks on sageli Helena.`);
const laiv=n=>E(`${n}, tāpat kā Laive, Laivi un Laidi, lielākoties ir plaši lietotā vārda Laine pārveidojums, ko izvēlējās retāku vārdu cienītāji.`,`${n}, как и Laive, Laivi и Laidi, — в основном переделка широко распространённого имени Laine, которую выбирали любители более редких имён.`,`${n}, like Laive, Laivi and Laidi, is mostly a reshaping of the widely used name Laine by people who liked rarer names.`,`${n}, kaip ir Laive, Laivi bei Laidi, dažniausiai yra plačiai vartojamo vardo Laine perdirbinys, kurį rinkosi retesnių vardų mėgėjai.`,`${n}, nagu ka Laive, Laivi ja Laidi, on enamasti haruldasemate nimede harrastajate teisendus «laiatarbenimest» Laine.`);
const silv=n=>E([`${n} (Silva, Silvi, Silvia, Silvy, Sylva, Sylvia) cēlies no romiešu meža un pļavu dieva Silvāna (Sylvanus) vārda. Rēja Silvija teikās ir Romula un Rema māte.`,`Igaunijā kopš 1934. gada starp šiem variantiem pārsvarā ir Silvi.`],[`${n} (Silva, Silvi, Silvia, Silvy, Sylva, Sylvia) восходит к имени римского бога лесов и лугов Сильвана (Sylvanus). Рея Сильвия в преданиях — мать Ромула и Рема.`,`В Эстонии с 1934 года среди этих вариантов преобладает Silvi.`],[`${n} (Silva, Silvi, Silvia, Silvy, Sylva, Sylvia) comes from the name of Sylvanus, the Roman god of forests and meadows. In legend Rhea Silvia is the mother of Romulus and Remus.`,`In Estonia Silvi has been the most frequent of these variants since 1934.`],[`${n} (Silva, Silvi, Silvia, Silvy, Sylva, Sylvia) kilęs iš romėnų miškų ir pievų dievo Silvano (Sylvanus) vardo. Pasak legendos, Rėja Silvija – Romulo ir Remo motina.`,`Estijoje nuo 1934 metų tarp šių variantų vyrauja Silvi.`],[`${n} ~ Silvi ~ Silvia ~ Silvy ~ Sylva ~ Sylvia pärineb roomlaste metsa- ja niidujumala Sylvanuse nimest. Rhea Silvia on pärimuslikult Romuluse ja Remuse ema.`,`Silvi on teisendite seas ülekaalus 1934. a. saadik.`]);
const joh=n=>E(`${n} ir Johannesa māsas vārds; tā īsās formas ir Anna jeb Hanna un Jāna jeb Jane. Krieviski Иоанна, angliski Jenny, franciski Jeanne un Jeanette, itāliski Giovanna, spāniski Juanita.`,`${n} — «сестринское» имя к Иоганнесу (Johannes); его сокращения — Анна или Ханна и Яана или Яне. По-русски Иоанна, по-английски Jenny, по-французски Jeanne и Jeanette, по-итальянски Giovanna, по-испански Juanita.`,`${n} is the sister name of Johannes; its short forms are Anna or Hanna and Ja(a)na or Jan(n)e. Russian has Ioanna, English Jenny, French Jeanne and Jeanette, Italian Giovanna and Spanish Juanita.`,`${n} – Johanneso „sesers“ vardas; jo trumpiniai – Ana arba Hana ir Jana arba Jane. Rusiškai Ioana, angliškai Jenny, prancūziškai Jeanne ir Jeanette, itališkai Giovanna, ispaniškai Juanita.`,`${n} on Johannese sõsarnimi; lühendid Anna ~ Hanna, Ja(a)na ~ Jan(n)e; vene Ioanna, inglise Jenny, prantsuse Jeanne ja Jeanette, itaalia Giovanna, hispaania Juanita.`);
