  Arčijs:H('Arčijs',X('Arčijs ir vārda Arhibalds angļu mīļvārds.','Arčijs — английская уменьшительная форма имени Арчибальд (Arhibalds).','Arčijs is the English pet form of Archibald (Arhibalds).','Arčijs – angliška maloninė vardo Archibaldas (Arhibalds) forma.','Arčijs on nime Archibald (Arhibalds) inglise hüüdvorm.'),rec('riga','c20q3')),
  Askolds:H('Askolds',X('Askolds darināts no senaugšvācu asc — «šķēps» — un waltan — «valdīt». Askolds bija arī Kijevas kņazs (862. gads).','Askolds образовано от древневерхненемецких asc — «копьё» — и waltan — «править». Аскольд был и князем Киева (862 год).','Askolds is formed from Old High German asc, “spear”, and waltan, “to rule”. Askold was also a prince of Kyiv (862).','Askolds sudarytas iš senosios aukštaičių vokiečių asc – „ietis“ – ir waltan – „valdyti“. Askoldas buvo ir Kijevo kunigaikštis (862 m.).','Askolds on moodustatud vanaülemsaksa sõnadest asc, „oda”, ja waltan, „valitsema”. Askold oli ka Kiievi vürst (862).'),rec('vidz','c20q1',1966)),
  Astrīda:H('Astrīda',X('Astrīda saistīta ar senskandināvu Asfridh — «dievs» un «skaists».','Astrīda связана с древнескандинавским Asfridh — «бог» и «прекрасный».','Astrīda is linked with Old Scandinavian Asfridh, “god” and “beautiful”.','Astrīda siejama su senųjų skandinavų Asfridh – „dievas“ ir „gražus“.','Astrīda on seotud muinasskandinaavia nimega Asfridh, „jumal” ja „ilus”.'),rec('riga',1905)),
  Audars:H('Audars',X('Audars bija vīrs, kurš 11. gadsimtā Zemgalē esot dalījis zeltu.','Audars — так звали человека, который, по преданию, в XI веке делил золото в Земгале.','Audars was a man who, according to tradition, shared out gold in Zemgale in the eleventh century.','Audaras – vyras, kuris, pasak padavimo, XI amžiuje Žiemgaloje dalijo auksą.','Audars oli mees, kes pärimuse järgi jagas 11. sajandil Zemgales kulda.'),null),
  Aļiks:H('Aļiks',X('Aļiks ir vārda Oļegs mīļvārds; Oļegs cēlies no senskandināvu Helge (haelgi — «cēlais, svētais»).','Aļiks — ласкательная форма имени Олег; Олег восходит к древнескандинавскому Helge (haelgi — «благородный, святой»).','Aļiks is a pet form of Oļegs (Oleg), which comes from Old Scandinavian Helge (haelgi, “noble, holy”).','Aļiks – vardo Olegas maloninė forma; Olegas kilęs iš senųjų skandinavų Helge (haelgi – „kilnus, šventas“).','Aļiks on nime Oļegs (Oleg) hüüdvorm; Oleg pärineb muinasskandinaavia nimest Helge (haelgi, „üllas, püha”).'),null),
  Brinda:H('Brinda',X('Brinda cēlusies no itāļu brindisi — «dzīru dziesma»; to saista ar Dž. Verdi operu «Traviata».','Brinda восходит к итальянскому brindisi — «застольная песня»; его связывают с оперой Дж. Верди «Травиата».','Brinda comes from Italian brindisi, “drinking song”, and is linked with Verdi’s opera La traviata.','Brinda kilusi iš italų brindisi – „puotos daina“; ji siejama su G. Verdžio opera „Traviata“.','Brinda pärineb itaalia sõnast brindisi, „joogilaul”, ja on seotud G. Verdi ooperiga „Traviata”.'),rec('ziemupe',1940)),
