  Dzeja:H('Dzeja',X('Dzeja ir latviešu vārds dzeja.','Dzeja — латышское слово dzeja — «поэзия».','Dzeja is the Latvian word dzeja, “poetry”.','Dzeja – latvių žodis dzeja – „poezija“.','Dzeja on läti sõna dzeja, „luule”.'),rec('jelg',1930)),
  Egmonts:H('Egmonts',X('Egmonts ir vārda Egmunds forma (senaugšvācu ecka — «zobens» — un munt — «patvērums, sargs»); tā sauc arī J. V. Gētes lugas «Egmonts» varoni.','Egmonts — форма имени Эгмунд (древневерхненемецкие ecka — «меч» — и munt — «защита, страж»); так зовут и героя драмы И. В. Гёте «Эгмонт».','Egmonts is a form of Egmunds (Old High German ecka, “sword”, and munt, “protection, guardian”); it is also the title hero of Goethe’s play Egmont.','Egmonts – vardo Egmundas forma (senosios aukštaičių vokiečių ecka – „kardas“ – ir munt – „globa, sargas“); taip vadinamas ir J. V. Gėtės dramos „Egmontas“ herojus.','Egmonts on nime Egmunds kuju (vanaülemsaksa ecka, „mõõk”, ja munt, „kaitse, valvur”); nii on nimetatud ka Goethe näidendi „Egmont” peategelane.'),rec('riga','c20q3',1970)),
  Egons:H('Egons',T.form('Egons','Eginhards'),rec('riga',1872,1915)),
  Elijs:H('Elijs',X('Elijs ir vārda Eliass forma; ebreju ʽElī — «augstais».','Elijs — форма имени Илья (Eliass); еврейское ʽElī — «высокий».','Elijs is a form of Eliass (Elias); Hebrew ʽElī means “the high one”.','Elijs – vardo Eliass forma; hebrajų ʽElī – „aukštasis“.','Elijs on nime Eliass kuju; heebrea ʽElī, „kõrge”.'),rec('riga',1973)),
  Elvīra:H('Elvīra',X('Elvīra cēlusies no senaugšvācu sieviešu vārda Alwara — «visu uzturētāja, aizsargātāja»; spāniski Alvira nozīmē «cēlā, pārākā».','Elvīra восходит к древневерхненемецкому женскому имени Alwara — «всех хранящая, защищающая»; испанское Alvira значит «благородная, превосходная».','Elvīra comes from the Old High German woman’s name Alwara, “keeper and protector of all”; Spanish Alvira means “noble, superior”.','Elvīra kilusi iš senosios aukštaičių vokiečių moters vardo Alwara – „visų globėja, saugotoja“; ispaniškai Alvira reiškia „kilnioji, pranašesnė“.','Elvīra pärineb vanaülemsaksa naisenimest Alwara, „kõige hoidja ja kaitsja”; hispaania Alvira tähendab „üllas, ülem”.'),rec('katlakalns',1874,1892)),
