  Nigra:H('Nigra',X('Nigra ir upes vārds (Nigra ir Abulas pieteka); latīņu nigra nozīmē «melna».','Nigra — название реки (Нигра — приток Абулы); латинское nigra значит «чёрная».','Nigra is a river name (the Nigra is a tributary of the Abula); Latin nigra means “black”.','Nigra – upės vardas (Nigra – Abulos intakas); lotynų nigra reiškia „juoda“.','Nigra on jõenimi (Nigra on Abula lisajõgi); ladina nigra tähendab „must”.'),rec('kandava',1940)),
  Nija:H('Nija',X('Nija cēlusies no vārdiem, kas beidzas ar -nija.','Nija образовано от имён, оканчивающихся на -nija.','Nija comes from names ending in -nija.','Nija kilusi iš vardų, kurie baigiasi -nija.','Nija pärineb -nija-lõpulistest nimedest.'),rec('vents','c20q3')),
  Nils:H('Nils',X('Nils ir vārdu Nikolauss un Kornēlijs forma; krievu Нил cēlies no latīņu Nilus — «Nīla (upe)».','Nils — форма имён Николай (Nikolauss) и Корнелий; русское Нил восходит к латинскому Nilus — «Нил (река)».','Nils is a form of Nikolauss and Kornēlijs; the Russian name Nil comes from Latin Nilus, “the Nile”.','Nils – vardų Nikolajus ir Kornelijus forma; rusų Nil kilęs iš lotynų Nilus – „Nilas (upė)“.','Nils on nimede Nikolauss ja Kornēlijs kuju; vene Nil pärineb ladina sõnast Nilus, „Niilus”.'),rec('malta','c20q1',1767)),
  Nita:H('Nita',X('Nita cēlusies no vārdiem, kas beidzas ar -nita.','Nita образовано от имён, оканчивающихся на -nita.','Nita comes from names ending in -nita.','Nita kilusi iš vardų, kurie baigiasi -nita.','Nita pärineb -nita-lõpulistest nimedest.'),rec('riga',1930)),
